--[[
    Prompts.lua  (Assistant)
    The starter prompt library: the same text as agent/prompts/*.md, which the launcher ships.
    Generated: edit the .md files, then run  python launcher/ai_setup.py --write-lua
]]--

Assistant = Assistant or {}
Assistant.PROMPTS = {
    { id = "tour-my-install",
      title = [[Tour my Open Vanilla folder]],
      summary = [[A safe first prompt: the agent looks around and explains what is where. It changes nothing.]],
      works = [[Your copy, read-only.]],
      text = [[Read CLAUDE.md, then look around this Open Vanilla folder without changing anything. Tell me in plain words: which addons I have in AddOns\Enabled and what each one does, whether Play Solo is set up (Realms\), and anything in Logs\ that looks like an error. End with three things you could help me do next.]] },
    { id = "first-addon",
      title = [[Make my first addon]],
      summary = [[A tiny addon that says hello and adds a slash command, explained line by line.]],
      works = [[Your copy (AddOns\Enabled).]],
      text = [[Read CLAUDE.md. Make me a small first addon called MyFirstAddon in AddOns\Enabled: when I log in it prints a friendly greeting with my character's name in chat, and /hello shows my level and current zone. Follow the Lua 5.0 rules for the Vanilla client. Explain each file and line simply, then tell me how to test it in game with /reload and how to remove it.]] },
    { id = "fix-addon-error",
      title = [[Fix an addon error]],
      summary = [[Paste the error from the game's error dialog and let the agent find and fix it.]],
      works = [[Your copy (your own or copied addons).]],
      text = [[Read CLAUDE.md. An addon shows a Lua error in game. Here is the error text: <paste the error here>. Find which addon and line it comes from, check Logs\ for anything related, explain the cause in plain words, back the file up, and fix it following the Lua 5.0 rules. If it is one of the shipped Open Vanilla addons, don't edit it in place: tell me, and suggest a report or a separate fix addon instead.]] },
    { id = "ui-theme",
      title = [[Make a UI theme]],
      summary = [[Restyle fonts, colours and frame positions with a small addon of your own.]],
      works = [[Your copy (a new addon in AddOns\Enabled).]],
      text = [[Read CLAUDE.md. Make me a small addon called MyTheme in AddOns\Enabled that restyles my interface: <describe the look you want, e.g. darker chat background, bigger font on the player and target frames, gold borders>. Keep everything in one addon I can switch off from the launcher, keep it Lua 5.0 safe, and add /mytheme to turn it on and off. Tell me how to test it with /reload.]] },
    { id = "xp-rate",
      title = [[Change my realm's XP rate]],
      summary = [[Faster (or slower) levelling on your own Solo world or hosted realm.]],
      works = [[Your own servers only (Play Solo, Open Vanilla Server).]],
      text = [[Read CLAUDE.md. I want <2x> experience on my own realm: <Play Solo / my Open Vanilla Server realm>. Find the right config file for that realm, back it up, and change Rate.XP.Kill, Rate.XP.Quest and Rate.XP.Explore. Show me the lines you changed, how to restart the realm, and how to undo it.]] },
    { id = "custom-npc-vendor",
      title = [[Add a custom NPC or vendor]],
      summary = [[A new vendor on your own server, written as a reviewable SQL file first.]],
      works = [[Your own servers only (the world database on this PC).]],
      text = [[Read CLAUDE.md. On my own <Play Solo / hosted> realm, add a custom vendor NPC called <name> who sells <items>. Use a new entry number above 190000, write the change as a .sql file in Agent\sql\ first and explain it to me before running anything, back up what you touch, and tell me the GM command to spawn the NPC where I stand (.npc add <entry>) and how to remove it again.]] },
    { id = "host-for-friends",
      title = [[Host a realm for friends]],
      summary = [[Step-by-step help getting Open Vanilla Server running and your friends connected.]],
      works = [[Your PC and your own realm.]],
      text = [[Read CLAUDE.md. Help me run my own realm for friends with Open Vanilla Server (openvanilla.app/host.html). Check whether SPP Classics is set up (Realms\Solo or C:\SPP_Classics_V2), walk me through Open Vanilla Server one step at a time, explain the choice between my home network and the internet (the internet shows my IP address to the people I invite), and if something fails, read Open Vanilla Server's logs and tell me what to fix. Don't change my router or firewall yourself: tell me what to do.]] },
    { id = "gm-commands",
      title = [[GM commands cheat sheet]],
      summary = [[Make yourself a GM on your own realm and get a cheat sheet that fits it.]],
      works = [[Your own servers only.]],
      text = [[Read CLAUDE.md. Help me use GM commands on my own <Play Solo / hosted / dedicated> realm: explain how to give my account GM level 3 there, then write me a one-page cheat sheet as Agent\gm-cheatsheet.md with the commands I'll use most (teleport, level up, add items, spawn and delete NPCs, server info), checked against this server's own .help output where you can.]] },
    { id = "backup",
      title = [[Back up my characters and settings]],
      summary = [[A one-click style backup of your addons, settings and realm data.]],
      works = [[Your copy and your own servers.]],
      text = [[Read CLAUDE.md. Make a backup of my Open Vanilla stuff into Backups\manual-<today's date>\: AddOns\, Settings\ (leave out any saved password), Game\benilla-config\ and the config files of my realms in Realms\. For realm characters, tell me how to use the launcher's Backup button or export the character database safely. Then write a short Backups\HOW-TO-RESTORE.txt.]] },
}
